import{_ as t,o as a,c as s,ab as r}from"./chunks/framework.DfnUYNhO.js";const k=JSON.parse('{"title":"現在の通信経路と環境の制限","description":"","frontmatter":{"title":"現在の通信経路と環境の制限","docId":"developer.transports","translationKey":"developer.transports","locale":"ja","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"11d31f98506b45ee544671e60ed105323f573e90405e126ab6c242d95a2ce964","order":200},"headers":[],"relativePath":"ja/developer/transports.md","filePath":"ja/developer/transports.md","lastUpdated":1795477225000}'),o={name:"ja/developer/transports.md"};function i(d,e,n,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">現在の通信経路と環境の制限 <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;現在の通信経路と環境の制限 {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>対象ビルドと環境に実在する通信経路を選びます。<a href="./control-api.html">Control API</a> と<a href="./collaboration.html">共同操作</a> を読みます。通信は直列化した操作を運び、別コアや独自の権限を作ってはいけません。</p><h2 id="choose-the-boundary" tabindex="-1">境界を選ぶ <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;境界を選ぶ {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>経路</th><th>現在の実装</th><th>主な制限</th></tr></thead><tbody><tr><td>デスクトップ WebView</td><td>Wry IPC と共有コントロールクライアント</td><td>GUI とスレッドの寿命はデスクトップ側</td></tr><tr><td>ローカル CLI</td><td>Unix ソケットまたは Windows 名前付きパイプ、明示的な stdio ホスト</td><td>アプリのホームと所有者が同一</td></tr><tr><td>ローカル ブラウザー</td><td>ネイティブ ループバック アダプターと <code>browser-transport.ts</code></td><td>ペアリング済みネイティブ ホスト。公開リモートサーバーではない</td></tr><tr><td>認証済み HTTPS/WSS ゲートウェイ</td><td>TLS・hello・権限・機能ゲートを備えた SDK/ブラウザー通信</td><td>リモートコマンドには明示的な許可が必要</td></tr><tr><td>インストール可能なリモート制御プラグイン</td><td><code>remote.controller.ticket</code> を使う WSS リレー上の <code>tiktools.remote-control</code></td><td>プラグインが所有し、リモートコードはホストにコンパイルされない</td></tr></tbody></table><p>TypeScript の通信インターフェースは <code>src/web/shared/api/control-transport.ts</code> にあります。リモート制御はホストバイナリの一部ではなく、インストール可能なプラグインです。すべてのコマンドは <code>HostCallPolicy</code>（<code>remote.command.dispatch</code>、<code>remote.pair.list</code>、<code>remote.grant.list</code>、<code>remote.grant.revoke</code>、<code>remote.controller.ticket</code>）を通過します。このビルドにはネイティブ peer/RTC 通信も Cloud Teams のホスト連携もありません。</p><h2 id="inspect-the-selected-route" tabindex="-1">選択した経路を調べる <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;選択した経路を調べる {#inspect-the-selected-route}&quot;">​</a></h2><p>ペアリングや制御操作の表示の前に、接続済みホストが対応するメソッドと機能を確認します:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>ペアリングと許可はプラグインが所有します。コントローラー チケットは短期・単一回限りで、<code>remote.grant.list</code> / <code>remote.grant.revoke</code> が権威ある情報源です。リレー接続は通信経路を示すだけで、RPC 権限を示すものではありません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と状況 {#expected-result-and-status}&quot;">​</a></h2><p>ローカル IPC とデスクトップ通信は確立済みです。リモート制御はインストール可能なプラグインと認証済みリレーで動作し、第 2 のホストランタイムではありません。ログインコードは 5 分の有効期限で接続済みデバイスに中継され、アカウント未設定時は OAuth にフォールバックします。Android のローカル IPC は計測対応 <code>mobile</code> ツール（<code>info</code> / <code>exec</code> / <code>tty</code>）で動作しますが、デスクトップ用ネイティブ アドオンと WebView は利用できません。</p><h2 id="recovery" tabindex="-1">復旧 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;復旧 {#recovery}&quot;">​</a></h2><p>切断は受け付けた操作の不確実性として扱います。再接続時は非公開の投影を無効化し、ID を再交渉し、有界ストリームを再開またはスナップショット化します。証明書チェックを緩めたり、リモート失敗後に黙ってローカル所有者にフォールバックしたりしてはいけません。期限切れチケットと失効した許可は fail-close にします。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>許可は最小権限かつ期限付きにし、再接続のたびに再確認します。ID、チケットの有効期限、許可の範囲、リレーへの到達性、フレーム サイズを個別に診断します。過大フレームは部分 RPC にならず、フレーム検証で拒否されます。実機 2 台の受け入れ前に、変更・失効したセッションを fixture で検証します。</p>`,16)])])}const u=t(o,[["render",i]]);export{k as __pageData,u as default};
